import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse(`{"title":"Download Customer Invoice PDF","description":"","frontmatter":{"outline":false,"examples":[{"id":"download-customer-invoice-pdf","title":"Download Invoice PDF","description":"Download an invoice as a PDF file.","request":"GET /api/shop/customer-invoices/1/pdf\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"Binary PDF file\\nContent-Type: application/pdf\\nContent-Disposition: attachment; filename=\\"invoice-1.pdf\\"\\n","commonErrors":[{"error":"404 Not Found","cause":"Invoice with specified ID does not exist or does not belong to the customer","solution":"Verify the invoice ID and ensure it belongs to the authenticated customer's orders"},{"error":"401 Unauthorized","cause":"Missing or invalid Bearer token","solution":"Login and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.md","filePath":"api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.md"}`),s={name:"api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.md"};function n(r,e,d,h,l,c){return a(),o("div",null,e[0]||(e[0]=[i(`<h1 id="download-customer-invoice-pdf" tabindex="-1">Download Customer Invoice PDF <a class="header-anchor" href="#download-customer-invoice-pdf" aria-label="Permalink to &quot;Download Customer Invoice PDF&quot;">​</a></h1><p>Download an invoice as a PDF file. The response is a binary PDF stream containing the full invoice document.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/customer-invoices/{id}/pdf</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>Customer invoice ID</td></tr></tbody></table><h2 id="response-200-ok" tabindex="-1">Response (200 OK) <a class="header-anchor" href="#response-200-ok" aria-label="Permalink to &quot;Response (200 OK)&quot;">​</a></h2><p>The response is a binary PDF file with the following headers:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td><code>application/pdf</code></td></tr><tr><td><code>Content-Disposition</code></td><td><code>attachment; filename=invoice-{date}.pdf</code> — the invoice date, e.g. <code>invoice-21-07-2026.pdf</code>, not the invoice ID</td></tr></tbody></table><h3 id="pdf-contents" tabindex="-1">PDF Contents <a class="header-anchor" href="#pdf-contents" aria-label="Permalink to &quot;PDF Contents&quot;">​</a></h3><p>The PDF document includes:</p><ul><li>Store information and logo</li><li>Billing and shipping addresses</li><li>Invoice line items with SKU, quantity, price, and totals</li><li>Financial summary (subtotal, tax, shipping, discount, grand total)</li><li>Invoice number, order number, and date</li></ul><h3 id="curl-example" tabindex="-1">cURL Example <a class="header-anchor" href="#curl-example" aria-label="Permalink to &quot;cURL Example&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api-demo.bagisto.com/api/shop/customer-invoices/1/pdf&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-STOREFRONT-KEY: pk_storefront_your_key_here&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer YOUR_CUSTOMER_TOKEN&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> invoice-001.pdf</span></span></code></pre></div><h2 id="error-responses" tabindex="-1">Error Responses <a class="header-anchor" href="#error-responses" aria-label="Permalink to &quot;Error Responses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Body <code>detail</code></th><th>Cause</th></tr></thead><tbody><tr><td><code>404</code></td><td><code>Customer invoice with ID &quot;999999&quot; not found</code></td><td>No such invoice, or it belongs to another customer&#39;s order.</td></tr><tr><td><code>403</code></td><td><code>Unauthenticated. Please login to perform this action</code></td><td>No customer Bearer token was sent.</td></tr><tr><td><code>401</code></td><td>—</td><td>The storefront key header was missing or wrong.</td></tr></tbody></table><p>An error answers with JSON even though the success path is binary, so branch on the status code before writing the body to a file.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Download invoice&quot; button</strong> — fetch with both auth headers and save the response body; the <code>downloadUrl</code> field on the invoice payload points at this same route.</li><li><strong>Attach an invoice to an email or ticket</strong> — the PDF is the only place the invoiced line items are available over REST.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Do not put this URL in an anchor tag</strong> — a browser navigation sends no <code>Authorization</code> or storefront-key header and the download fails with <code>403</code>. Fetch it in code and hand the blob to the user.</li><li><strong>Take the filename from <code>Content-Disposition</code></strong> — it is built from the invoice date, so guessing <code>invoice-{id}.pdf</code> produces the wrong name.</li><li><strong>Check the response content type first</strong> — a failure returns JSON with the same <code>200</code>-style plumbing on the client, and saving it produces an unreadable &quot;PDF&quot;.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get All Customer Invoices</a> — every invoice raised against the customer&#39;s orders</li><li><a href="/api/rest-api/shop/customer-invoices/get-customer-invoice.html">Get Single Customer Invoice</a> — one invoice by id</li><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> — the customer&#39;s order history</li></ul>`,25)]))}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
